"""Long-term memory: written on every turn, read back by embedding similarity."""


class MemoryStore:
    def __init__(self, index, embedder):
        self.index = index
        self.embedder = embedder

    def add_memory(self, text, user_id):
        """Append what the user just told us."""
        self.index.upsert(
            id=new_id(),
            vector=self.embedder.embed(text),
            metadata={"user_id": user_id, "text": text},
        )

    def recall(self, question, user_id, top_k=8):
        hits = self.index.similarity_search(
            self.embedder.embed(question), top_k=top_k, filter={"user_id": user_id}
        )
        return [h.metadata["text"] for h in hits]


def build_prompt(question, store, user_id):
    return "\\n".join(store.recall(question, user_id)) + "\\n\\n" + question

good.service/memory.py:
"""Long-term memory with a validity window.

A memory is a claim about a world that changes, so writing a new one has to settle
what it does to the ones it contradicts. Retrieval reads only what is still valid.
"""


class MemoryStore:
    def __init__(self, index, embedder):
        self.index = index
        self.embedder = embedder

    def add_memory(self, text, user_id, observed_at):
        """Append the new claim and close out the claims it replaces."""
        for prior in self._contradicted(text, user_id):
            self.invalidate_fact(prior, at=observed_at)
        self.index.upsert(
            id=new_id(),
            vector=self.embedder.embed(text),
            metadata={
                "user_id": user_id,
                "text": text,
                "valid_from": observed_at,
                "valid_to": None,
            },
        )

    def invalidate_fact(self, record, at):
        """Close a claim rather than deleting it, so history stays answerable."""
        self.index.update(record.id, metadata={"valid_to": at})

    def recall(self, question, user_id, top_k=8, at=None):
        hits = self.index.similarity_search(
            self.embedder.embed(question), top_k=top_k, filter={"user_id": user_id}
        )
        return [h.metadata["text"] for h in hits if self._valid(h, at)]

    def _valid(self, hit, at):
        closed = hit.metadata.get("valid_to")
        return closed is None or (at is not None and at < closed)


def build_prompt(question, store, user_id):
    return "\\n".join(store.recall(question, user_id)) + "\\n\\n" + question
